// Asteroid Dodger Game
// Assumes an HTML canvas element with id="game" exists.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // no canvas, abort
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  const ship = {
    x: width / 2,
    y: height - 40,
    radius: 15,
    speed: 5,
    moveLeft: false,
    moveRight: false,
    draw() {
      ctx.fillStyle = 'white';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y - this.radius);
      ctx.lineTo(this.x - this.radius, this.y + this.radius);
      ctx.lineTo(this.x + this.radius, this.y + this.radius);
      ctx.closePath();
      ctx.fill();
    },
    update() {
      if (this.moveLeft) this.x -= this.speed;
      if (this.moveRight) this.x += this.speed;
      // keep within bounds
      this.x = Math.max(this.radius, Math.min(width - this.radius, this.x));
    }
  };

  const asteroids = [];
  const asteroidSpawnInterval = 1000; // ms
  let lastSpawn = 0;
  const asteroidSpeed = 2;
  const asteroidRadius = 20;

  let lives = 3;
  let startTime = performance.now();
  let gameOver = false;

  // Input handling
  document.addEventListener('keydown', e => {
    if (e.code === 'ArrowLeft') ship.moveLeft = true;
    if (e.code === 'ArrowRight') ship.moveRight = true;
  });
  document.addEventListener('keyup', e => {
    if (e.code === 'ArrowLeft') ship.moveLeft = false;
    if (e.code === 'ArrowRight') ship.moveRight = false;
  });

  function spawnAsteroid() {
    const x = Math.random() * (width - asteroidRadius * 2) + asteroidRadius;
    asteroids.push({ x, y: -asteroidRadius, radius: asteroidRadius });
  }

  function update(delta) {
    if (gameOver) return;
    // spawn
    if (performance.now() - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }
    // ship
    ship.update();
    // asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += asteroidSpeed;
      // collision
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.radius) {
        lives--;
        asteroids.splice(i, 1);
        if (lives <= 0) {
          gameOver = true;
        }
        continue;
      }
      // remove off-screen
      if (a.y - a.radius > height) {
        asteroids.splice(i, 1);
      }
    }
  }

  function render() {
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, width, height);
    // ship
    ship.draw();
    // asteroids
    ctx.fillStyle = 'gray';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // UI
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Lives: ${lives}`, 10, 20);
    const score = Math.floor((performance.now() - startTime) / 1000);
    ctx.fillText(`Score: ${score}s`, 10, 40);
    if (gameOver) {
      ctx.textAlign = 'center';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const delta = timestamp - lastTime;
    lastTime = timestamp;
    update(delta);
    render();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
